require __DIR__.'/app/bootstrap.php';$ctx=growth_seller_context('products');$u=$ctx['user'];$uid=(int)$ctx['owner_id'];$msg=$err=null;$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='archive'){db()->prepare("UPDATE store_products SET status='archived' WHERE id=? AND seller_user_id=?")->execute([$id,$uid]);$msg='Product archived.';}else{$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('Product title required.');$type=in_array($_POST['product_type']??'new',['new','used','digital'],true)?$_POST['product_type']:'new';if($type==='digital'&&!setting_bool('store_digital_enabled',true))throw new RuntimeException('Digital products are disabled.');$sale=in_array($_POST['sale_mode']??'fixed',['fixed','auction'],true)?$_POST['sale_mode']:'fixed';if($sale==='auction'&&!setting_bool('store_auction_enabled',true))throw new RuntimeException('Auctions are disabled.');$business=(int)($_POST['business_id']??0)?:null;if($business){$q=db()->prepare('SELECT id FROM businesses WHERE id=? AND owner_id=?');$q->execute([$business,$uid]);if(!$q->fetchColumn())throw new RuntimeException('Invalid business.');}$image=trim((string)($_POST['image_url']??''));$up=store_upload_image($_FILES['image']??[]);if($up)$image=$up;$digital=$id?(string)(store_product($id)['digital_file_path']??''):'';if($type==='digital'){$file=store_upload_digital($_FILES['digital_file']??[]);if($file)$digital=$file;if(!$digital)throw new RuntimeException('Digital product file is required.');}$status=setting_bool('store_seller_approval_required',true)?'pending':'published';$data=[$uid,$business,(int)$_POST['category_id'],(int)($_POST['city_id']??0)?:null,$type,$sale,$title,store_slug($_POST['slug']?:$title,$id),trim((string)$_POST['short_description'])?:null,trim((string)$_POST['description'])?:null,$image?:null,$digital?:null,max(0,(float)$_POST['price']),max(0,(float)($_POST['compare_price']??0)),max(0,(int)($_POST['stock']??1)),trim((string)$_POST['condition_notes'])?:null,max(0,(float)($_POST['shipping_charge']??0)),isset($_POST['allow_cod'])&&$type!=='digital'?1:0,isset($_POST['allow_advance'])?1:0,trim((string)$_POST['location_text'])?:null,$status];if(!$id){$limit=growth_entitlement_limit($uid,'products_limit',999999);$count=(int)growth_scalar("SELECT COUNT(*) FROM store_products WHERE seller_user_id=? AND status<>'archived'",[$uid]);if($count>=$limit)throw new RuntimeException('Your subscription product limit has been reached.');}if($id){$q=db()->prepare('SELECT id FROM store_products WHERE id=? AND seller_user_id=?');$q->execute([$id,$uid]);if(!$q->fetchColumn())throw new RuntimeException('Product not found.');db()->prepare('UPDATE store_products SET seller_user_id=?,business_id=?,category_id=?,city_id=?,product_type=?,sale_mode=?,title=?,slug=?,short_description=?,description=?,image_url=?,digital_file_path=?,price=?,compare_price=?,stock=?,condition_notes=?,shipping_charge=?,allow_cod=?,allow_advance=?,location_text=?,status=? WHERE id=?')->execute(array_merge($data,[$id]));}else db()->prepare('INSERT INTO store_products(seller_user_id,business_id,category_id,city_id,product_type,sale_mode,title,slug,short_description,description,image_url,digital_file_path,price,compare_price,stock,condition_notes,shipping_charge,allow_cod,allow_advance,location_text,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$msg=$status==='pending'?'Product submitted for admin approval.':'Product published.';}
}catch(Throwable $e){$err=$e->getMessage();}}
